"use client";

/**
 * Card. A Panel with an anatomy, so every card in a product is spaced the
 * same way: optional media flush to the edges, a header (title, description,
 * one action on the right), a body, and a footer whose controls are `sm`.
 *
 * Give it `href` or `onClick` and the whole card is pressable: the title
 * becomes the link or button, stretched over the card, so a screen reader
 * hears one name and the card has one focus ring. It presses a pixel into
 * the surface and sends Panel's ripple from where you pressed; the header
 * action and the footer's controls stay their own targets on top.
 *
 * Closed: the slots are props, the spacing is `size` (sm/md/lg padding
 * steps), and there is no className. Built on Panel's material and
 * useRippleSurface.
 */
import { useRef, type MouseEventHandler, type ReactNode } from "react";
import { useSoundOptional } from "echo-ui-core/sound";
import { useRippleSurface } from "../panel";
import { SizeProvider, type ControlSize } from "../size";
import "./card.css";

export interface CardProps {
  /** The card's name. With `href` or `onClick`, it's also the link or button. */
  title: ReactNode;
  /** A line under the title. */
  description?: ReactNode;
  /** One control at the header's end: a menu, a toggle, a small button. */
  action?: ReactNode;
  /** An image, chart or preview across the top, flush to the edges. */
  media?: ReactNode;
  /** The body. */
  children?: ReactNode;
  /** Actions along the bottom; their controls default to `sm`. */
  footer?: ReactNode;
  /** `raised` plastic (default), or a `screen` well for a readout. */
  variant?: "raised" | "screen";
  /** Padding and gaps: `sm` for dense dashboards, `md` (default), `lg` for a feature. */
  size?: ControlSize;
  /** The whole card goes here. */
  href?: string;
  /** The whole card does this. */
  onClick?: MouseEventHandler<HTMLElement>;
  /** The title's heading level. Default 3. */
  headingLevel?: 2 | 3 | 4;
}

export function Card({
  title,
  description,
  action,
  media,
  children,
  footer,
  variant = "raised",
  size = "md",
  href,
  onClick,
  headingLevel = 3,
}: CardProps) {
  const interactive = href !== undefined || onClick !== undefined;
  const root = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const sound = useSoundOptional();
  useRippleSurface(root, canvas, { enabled: interactive });
  const Heading = `h${headingLevel}` as const;
  const press: MouseEventHandler<HTMLElement> = (e) => {
    sound?.play("tap");
    onClick?.(e);
  };

  const name = !interactive ? (
    title
  ) : href !== undefined ? (
    <a className="echo-card__link" href={href} onClick={onClick ? press : () => sound?.play("tap")}>
      {title}
    </a>
  ) : (
    <button type="button" className="echo-card__link" onClick={press}>
      {title}
    </button>
  );

  return (
    <div
      ref={root}
      className="echo-panel echo-card"
      data-variant={variant}
      data-size={size}
      data-interactive={interactive ? "" : undefined}
    >
      {interactive ? <canvas ref={canvas} className="echo-panel__ripple" aria-hidden="true" /> : null}
      <div className="echo-card__inner">
        {media ? <div className="echo-card__media">{media}</div> : null}
        <div className="echo-card__header">
          <div className="echo-card__heading">
            <Heading className="echo-card__title">{name}</Heading>
            {description ? <p className="echo-card__description">{description}</p> : null}
          </div>
          {action ? <div className="echo-card__action">{action}</div> : null}
        </div>
        {children ? <div className="echo-card__body">{children}</div> : null}
        {footer ? (
          <SizeProvider size="sm">
            <div className="echo-card__footer">{footer}</div>
          </SizeProvider>
        ) : null}
      </div>
    </div>
  );
}

/**
 * Card. Panel's material with a fixed anatomy. Padding and gaps are the
 * `size` steps; media runs to the edges; an interactive card presses a pixel
 * into the surface. The root is a Panel (panel.css gives the material).
 */
.echo-card {
  --card-pad: var(--echo-space-9);
  --card-gap: var(--echo-space-6);
  /* A column the inner layer fills, so a card stretched by its grid row is
     pressable (and ringed) all the way down. */
  display: flex;
  flex-direction: column;
  /* The padding is the inner layer's, so the stretched link covers the
     whole card from inside it without reaching past any box. */
  padding: 0;
  min-width: 0;
  color: var(--echo-text);
}
.echo-card[data-size="sm"] {
  --card-pad: var(--echo-space-7);
  --card-gap: var(--echo-space-4);
}
.echo-card[data-size="lg"] {
  --card-pad: var(--echo-space-11);
  --card-gap: var(--echo-space-8);
}
.echo-card__inner {
  flex: 1;
  position: relative;
  z-index: var(--echo-z-raised, 1);
  display: flex;
  flex-direction: column;
  gap: var(--card-gap);
  min-width: 0;
  padding: var(--card-pad);
  border-radius: inherit;
}
.echo-card__media {
  margin: calc(-1 * var(--card-pad)) calc(-1 * var(--card-pad)) 0;
  overflow: hidden;
}
.echo-card__media > :is(img, video, svg, canvas) {
  display: block;
  width: 100%;
  height: auto;
}
.echo-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--echo-space-6);
  min-width: 0;
}
.echo-card__heading {
  display: grid;
  gap: var(--echo-space-2);
  min-width: 0;
}
.echo-card__title {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: var(--echo-text-lg);
  font-weight: var(--echo-weight-semibold, 600);
  line-height: var(--echo-leading-snug, 1.4);
  color: var(--echo-text);
}
.echo-card[data-size="sm"] .echo-card__title {
  font-size: var(--echo-text-md);
}
.echo-card[data-size="lg"] .echo-card__title {
  font-size: var(--echo-text-xl);
}
.echo-card__description {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: var(--echo-text-sm);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}
.echo-card__body {
  min-width: 0;
  font-size: var(--echo-text-md);
  line-height: var(--echo-leading-body, 1.55);
  color: var(--echo-text-dim);
}
.echo-card__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--echo-space-4);
  padding-block-start: var(--card-gap);
  border-block-start: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}

/* Interactive: the title is the link, stretched over the whole card. */
.echo-card__link {
  all: unset;
  cursor: pointer;
  color: inherit;
}
.echo-card__link::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: var(--echo-z-raised, 1);
  border-radius: inherit;
}
/* The header action and the footer's controls stay their own targets. */
.echo-card__action,
.echo-card__footer {
  position: relative;
  z-index: var(--echo-z-top, 2);
}
.echo-card[data-interactive] {
  cursor: pointer;
  transition:
    transform var(--echo-duration-tick) ease,
    box-shadow var(--echo-duration-swap) ease;
}
/* Reached for, it lifts toward the light; pressed, it sinks a pixel. */
@media (hover: hover) {
  .echo-card[data-interactive][data-variant="raised"]:hover {
    box-shadow: var(
      --echo-shadow-lifted,
      0 1px 0 rgb(255 255 255 / calc(0.07 * var(--echo-gloss, 1))),
      0 10px 22px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.45 * var(--echo-shade, 1) * 100%), transparent)
    );
  }
}
.echo-card[data-interactive]:active:not(:has(.echo-card__action:active, .echo-card__footer:active)) {
  transform: translateY(1px);
}
.echo-card[data-interactive]:has(.echo-card__link:focus-visible) {
  outline: 2px solid transparent;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}
@media (prefers-reduced-motion: reduce) {
  .echo-card[data-interactive] {
    transition: none;
  }
  .echo-card[data-interactive]:active {
    transform: none;
  }
}
@media (forced-colors: active) {
  .echo-card {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
  .echo-card[data-interactive]:has(.echo-card__link:focus-visible) {
    outline: 2px solid Highlight;
  }
}
